#include <unordered_map>
using namespace std;


class Solution {
public:
    ListNode* removeZeroSumSublists(ListNode* head) {
        ListNode* dummy = new ListNode(0);
        dummy->next = head;
        unordered_map<int, ListNode*> sumMap;
        int sum = 0;
        for (ListNode* node = dummy; node; node = node->next) {
            sum += node->val;
            sumMap[sum] = node;
        }
        sum = 0;
        for (ListNode* node = dummy; node; node = node->next) {
            sum += node->val;
            node->next = sumMap[sum]->next;
        }
        return dummy->next;
    }
};
